params.command:
$ErrorActionPreference='Stop'
$repo=Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
git -C $repo fetch origin --prune
$branches=@(
'agent/bridge-uia-native-20260929',
'agent/control-test-narrow-test-scope-only-build-a-r-20260928133350-vrokm',
'agent/launch-observation-atomicity-20260928',
'agent/swarm-contract-v3-20260929-0540',
'agent-bridge',
'codex/complete-mod-workflows',
'fix/codex-quota-dispatch-circuit-20260929'
)
$out=@()
foreach($b in $branches){
  git -C $repo show-ref --verify --quiet ("refs/remotes/origin/"+$b)
  if($LASTEXITCODE -ne 0){$out += [pscustomobject]@{branch=$b;state='missing'}; continue}
  $tip=(git -C $repo rev-parse ("origin/"+$b)).Trim()
  $counts=(git -C $repo rev-list --left-right --count ("origin/main...origin/"+$b)).Trim() -split '\s+'
  $cherry=@(git -C $repo cherry origin/main ("origin/"+$b))
  $plus=@($cherry | Where-Object {$_ -like '+ *'})
  $minus=@($cherry | Where-Object {$_ -like '- *'})
  $subjects=@()
  foreach($line in $plus){
    $sha=($line -split '\s+')[1]
    $subjects += (git -C $repo show -s --format='%h %s' $sha).Trim()
  }
  $out += [pscustomobject]@{
    branch=$b; tip=$tip; behind=[int]$counts[0]; ahead=[int]$counts[1];
    patch_unique_count=$plus.Count; patch_equivalent_count=$minus.Count;
    patch_unique_commits=$subjects
  }
}
[pscustomobject]@{main=(git -C $repo rev-parse origin/main).Trim(); branches=$out} | ConvertTo-Json -Depth 6
